Algorithm TresNotas
  Dimension notas[3] As Integer;
  notas[0] <- 7;
  notas[1] <- 9;
  notas[2] <- 4;
  Write notas[1];
EndAlgorithm

Algorithm DiasCalurosos
  Dimension dias[7] As String;
  Dimension temperaturas[7] As Integer;
  dias[0] <- "lunes";
  dias[1] <- "martes";
  dias[2] <- "miércoles";
  dias[3] <- "jueves";
  dias[4] <- "viernes";
  dias[5] <- "sábado";
  dias[6] <- "domingo";
  Define suma As Integer <- 0;
  For i <- 0 To 6 Do
    Read temperaturas[i];
    suma <- suma + temperaturas[i];
  EndFor
  Define promedio As Real <- suma / 7;
  Define calurosos As Integer <- 0;
  For i <- 0 To 6 Do
    If temperaturas[i] > promedio Then
      Write dias[i];
      calurosos <- calurosos + 1;
    EndIf
  EndFor
  If calurosos = 0 Then
    Write "Ningún día";
  EndIf
EndAlgorithm
